export class NdefUtil {
  // Convert string to UTF-8 bytes
  private static stringToBytes(str: string): number[] {
    const encoder = new TextEncoder();
    const uint8Array = encoder.encode(str);
    return Array.from(uint8Array);
  }

  // Create NDEF Text Record payload
  private static encodeTextPayload(text: string, languageCode: string = 'en'): number[] {
    const lang = languageCode.trim().toLowerCase();
    const langBytes = this.stringToBytes(lang);
    const textBytes = this.stringToBytes(text);

    const payload = [langBytes.length, ...langBytes, ...textBytes];
    return payload;
  }

  // Create NDEF Text Record
  public static createTextRecord(
    text: string,
    languageCode: string = 'en'
  ): { tnf: number; type: number[]; id: number[]; payload: number[] } {
    const payload = this.encodeTextPayload(text, languageCode);
    return {
      tnf: 0x01, // TNF_WELL_KNOWN
      type: [0x54], // RTD_TEXT ('T')
      id: [],
      payload
    };
  }
}
